      const cli = clienteSL();
      const cartao = agenteSL(cli, 'sl2', { subagent_type: 'Explore', description: 'x', prompt: 'oi', run_in_background: true, model: 'sonnet' });
      const extras = cartao.querySelector('.sub-pedido-extras');
