  tudoOk &= ok(/chegaram 2 de 3/.test(notaArq.textContent) && /gigante\.iso/.test(notaArq.textContent) && /teto/.test(notaArq.textContent),
    `e o resumo diz quem falhou e por quê ("${notaArq.textContent}")`);
