    const pino1 = grupo1?.querySelector('.conversa-pino')?.textContent?.trim();
    tudoOk &= ok(pino1 === '●', `G1: pino de running é ● (${pino1})`);
    const nome1 = grupo1?.querySelector('.conversa-nome')?.textContent;
